"""Render markdown tables from branch_dispatch_results.json. Usage: render_branch_tables.py <results.json> <out.md>"""
import json, sys
d = json.load(open(sys.argv[1])); runs = d["runs"]; A = d["per_arm"]
def f(x, nd=2): return "-" if x is None else (f"{x:.{nd}f}" if isinstance(x, float) else str(x))
out = ["## T1. Per-run summary (observable artifacts only)", "", "| Run | Arm | Status | Gold rank | Tool calls | API calls | Cost USD | Duration s | Retries | First command | Gold first exposed | Buggy line shown | Calls after gold | Chain path | Route |", "|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|"]
for r in runs: out.append(f"| {r['run_id'].split('/')[1]} | {r['arm']} | {r['status']} | {r['gold_rank']} | {r['tool_call_count']} | {r['api_calls']} | {f(r['cost_usd'],4)} | {round((r['timing']['duration_ms'] or 0)/1000)} | {r['timing']['provider_retry_lines']} | `{(r['info_distance']['first_command'] or '')[:55]}` | {r['gold_first_exposed_step']} | {r['buggy_line_first_shown']} | {r['info_distance']['calls_after_first_gold']} | {r['chain']['chain_path']} | {r['chain']['route']} |")
out += ["", "## T2. Per-arm aggregates (n = 5 each; descriptive only)", "", "| Metric | CONTROL | BRANCH TREATMENT |", "|---|---|---|"]
keys = [("Completed / timeout", lambda a: f"{a['completed']} / {a['timeout']}"), ("Acc@1 / @3 / @5 / @10 (completed runs)", lambda a: " / ".join(f(a[k], 2) for k in ("acc_at_1", "acc_at_3", "acc_at_5", "acc_at_10"))), ("MRR (completed)", lambda a: f(a["mrr"], 3)), ("Acc@1 all-runs (timeout = miss) / MRR all-runs", lambda a: f"{f(a['acc_at_1_all_runs'],2)} / {f(a['mrr_all_runs'],3)}"),
        ("Gold ranks", lambda a: str(a["gold_ranks"])), ("Tool calls (list); mean / median", lambda a: f"{a['tool_calls']}; {a['tool_calls_mean_median'][0]} / {a['tool_calls_mean_median'][1]}"), ("API calls (list); mean", lambda a: f"{a['api_calls']}; {a['api_calls_mean_median'][0]}"), ("Gold first exposed step (list); mean / median", lambda a: f"{a['first_gold_step']}; {a['first_gold_step_mean_median'][0]} / {a['first_gold_step_mean_median'][1]}"),
        ("Buggy line first shown (list)", lambda a: str(a["buggy_line_step"])), ("Tool calls before first gold (list)", lambda a: str(a["calls_to_first_gold"])), ("Calls after gold (list); mean", lambda a: f"{a['calls_after_gold']}; {a['calls_after_gold_mean_median'][0]}"), ("Contract-evidence markers displayed per run", lambda a: str(a["contract_retrieval_count"])), ("Runs with contract evidence before rank / with NEW evidence after gold", lambda a: f"{a['runs_with_contract_evidence_before_rank']} / {a['runs_with_new_contract_evidence_after_gold']}"),
        ("Tests executed per run", lambda a: str(a["tests_executed"])), ("Source files opened per run", lambda a: str(a["source_files_opened"])), ("Unique search queries per run", lambda a: str(a["unique_search_queries"])), ("Novel-vocabulary events / runs", lambda a: f"{a['novel_vocab_events']} / {a['runs_with_novel_vocab']}"), ("build.properties observably used", lambda a: str(a["build_properties_observably_used"])), ("Durations s", lambda a: str(a["durations_s"])), ("Provider retry lines", lambda a: str(a["provider_retry_lines_total"])), ("Cost USD", lambda a: f(a["total_cost_usd"], 4))]
for lab, g in keys: out.append(f"| {lab} | {g(A['CONTROL'])} | {g(A['BRANCH_TREATMENT'])} |")
T = A["BRANCH_TREATMENT"]
if T.get("routes"):
    out += ["", "## T3. Chain completion (BRANCH TREATMENT)", "", "| Metric | Value |", "|---|---|", f"| Full five-hop sequential traversal (each hop by name after the previous call was shown) | {f(T['full_five_hop_traversal_rate'],2)} |", f"| All hops shown in order (any command) | {f(T['all_hops_shown_in_order_rate'],2)} |", f"| Lexical bypass | {f(T['lexical_bypass_rate'],2)} |", f"| Repository-wide shortcut | {f(T['repository_wide_shortcut_rate'],2)} |", f"| Direct gold search before hop 4's call | {f(T['direct_gold_search_rate'],2)} |", f"| Abandoned chain (submitted without exposing the gold) | {T['abandoned_chain']} |", f"| Timeout before gold | {T['timeout_before_gold']} |", f"| Runs reaching H1 / H2 / H3 / H4 / H5 | " + " / ".join(str(T['reached_per_hop'][t]) for t in ('H1','H2','H3','H4','H5')) + " |", f"| Skipped hops per run | {T['skipped_hops']} |", "| Routes | " + "; ".join(f"{k}: {v}" for k, v in T["routes"].items()) + " |"]
    out += ["", "## T4. Per-run chain flags (BRANCH TREATMENT)", "", "| Run | reached H1 | H2 | H3 | H4 | H5 | sequential by name | skipped | lexical bypass | repo-wide shortcut | direct gold search | abandoned | timeout before gold | gold exposed by name |", "|---|---|---|---|---|---|---|---|---|---|---|---|---|---|"]
    for r in runs:
        if r["arm"] != "TREATMENT": continue
        c = r["chain"]; out.append(f"| {r['run_id'].split('/')[1]} | " + " | ".join(str(c['reached'][t]) for t in ('H1','H2','H3','H4','H5')) + f" | {c['followed_all_five_sequentially']} | {','.join(c['skipped_hops']) or 'none'} | {c['lexical_bypass']} | {c['repository_wide_shortcut']} | {c['direct_gold_search']} | {c['abandoned_chain']} | {c['timeout_before_gold']} | {c['gold_exposed_by_name']} |")
    out += ["", "## T5. Information distance per run (BRANCH TREATMENT): first exposure step of each node and increments", "", "| Run | facade | H1 | H2 | H3 | H4 | H5 (gold) | calls→H1 | H1→H2 | H2→H3 | H3→H4 | H4→H5 | calls after gold | contract markers | tests | files opened | unique searches |", "|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|"]
    for r in runs:
        if r["arm"] != "TREATMENT": continue
        e = r["chain"]["exposure_steps"]; inc = r["chain"]["increments"]; i = r["info_distance"]
        out.append(f"| {r['run_id'].split('/')[1]} | " + " | ".join(f(e.get(t)) for t in ('facade','H1','H2','H3','H4','H5')) + " | " + " | ".join(f(inc.get(k)) for k in ('incremental_to_H1','incremental_to_H2','incremental_to_H3','incremental_to_H4','incremental_to_H5')) + f" | {f(i['calls_after_first_gold'])} | {i['external_contract_retrieval_count']} | {i['tests_executed_count']} | {len(i['source_files_opened'])} | {i['unique_search_queries']} |")
if T.get("dispatch_routes"):
    out += ["", "## T5b. Dispatch resolution (BRANCH TREATMENT)", "", "| Metric | Value |", "|---|---|", f"| Dispatch resolved (next stage exposed before submission) | {f(T['dispatch_resolution_success_rate'],2)} |", "| Routes | " + "; ".join(f"{k}: {v}" for k, v in T["dispatch_routes"].items()) + " |", f"| Calls spent resolving (H3 body → next stage exposed), list; mean / median | {T['calls_spent_resolving']}; {T['calls_spent_resolving_mean_median'][0]} / {T['calls_spent_resolving_mean_median'][1]} |", f"| of which dispatch-directed (mention Folding/fold/STANDARD/StandardFolding), list; mean / median | {T['dispatch_directed_calls']}; {T['dispatch_directed_calls_mean_median'][0]} / {T['dispatch_directed_calls_mean_median'][1]} |", f"| Binding and implementation read in the same command | {T['binding_and_impl_read_together']} |", f"| Files opened while resolving (per run) | {T['files_opened_while_resolving']} |", f"| Searches issued while resolving (per run) | {T['searches_while_resolving']} |", f"| Detour files opened while resolving | {T['detour_files']} |", f"| Backtracked to the boundary after resolution | {T['backtracked']} |", f"| Ranked an earlier hop instead of the gold | {T['ranked_earlier_hop_instead_of_gold']} |", f"| Ranked the abstraction/implementation first | {T['ranked_interface_or_impl_first']} |", f"| Abandoned chain | {T['abandoned_chain_count']} |", f"| Binding line first shown (step, per run) | {T['binding_line_shown']} |", f"| Implementation first shown (step, per run) | {T['impl_first_shown']} |", f"| First search for the abstraction (step, per run) | {T['first_search_for_interface']} |", f"| Runs using javap/jshell | {T['javap_jshell_used']} |"]
    out += ["", "## T5c. Per-run dispatch resolution (BRANCH TREATMENT)", "", "| Run | H3 body shown | abstraction searched | binding shown | impl shown | next stage exposed | calls spent | files opened | searches | detours | route | backtracked | resolving command |", "|---|---|---|---|---|---|---|---|---|---|---|---|---|"]
    for r in runs:
        if r["arm"] != "TREATMENT": continue
        d = r["dispatch"]; out.append(f"| {r['run_id'].split('/')[1]} | {f(d['first_encounter_abstraction_step'])} | {f(d['first_search_for_interface'])} | {f(d['binding_line_first_shown'])} | {f(d['impl_first_shown'])} | {f(d['resolved_step'])} | {f(d['calls_spent_resolving'])} | {', '.join(d['files_opened_while_resolving']) or '-'} | {d['searches_while_resolving']} | {', '.join(d['detour_files_while_resolving']) or 'none'} | {d['route']} | {d['backtracked_to_boundary_after_resolution']} | `{d['resolving_cmd'][:80]}` |")
if T.get("branch"):
    Bg = T["branch"]
    out += ["", "## T5d. Branch resolution and attribution (BRANCH TREATMENT)", "", "| Metric | Value |", "|---|---|", f"| Selector discovered / condition line shown | {Bg['selector_discovered']} / {Bg['condition_shown']} |", f"| Both implementations discovered (named) / both opened (content shown) | {Bg['both_implementations_discovered']} / {Bg['both_implementations_opened']} |", f"| Wrong branch (NarrowFolding) inspected first / followed / ignored | {Bg['wrong_branch_inspected_first']} / {Bg['wrong_branch_followed']} / {Bg['ignored_alternate']} |", f"| Backtracking to the dispatch layer after resolution | {Bg['backtracking']} |", f"| Runtime input source (`width = Integer.SIZE`) shown before resolution / condition shown before resolution / jshell on the dispatch | {Bg['width_source_shown_before_resolution']} / {Bg['condition_shown_before_resolution']} / {Bg['jshell_on_dispatch']} |", "| Rank-1 categories | " + "; ".join(f"{k}: {v}" for k, v in Bg["rank1_categories"].items()) + " |", f"| Discovery success / attribution failures | {Bg['discovery_success']} / {Bg['attribution_failures']} |", f"| Ranked (anywhere in top-10): selector / abstraction / wrong implementation / wrapper / facade | {Bg['ranked_selector']} / {Bg['ranked_abstraction']} / {Bg['ranked_wrong_implementation']} / {Bg['ranked_wrapper']} / {Bg['ranked_facade']} |", f"| Rank of NarrowFolding / facade / StandardFolding per run | {Bg['rank_of_narrow']} / {Bg['rank_of_facade']} / {Bg['rank_of_wrapper']} |", f"| First shown (step): selector / condition / StandardFolding / NarrowFolding | {Bg['selector_first_shown']} / {Bg['condition_first_shown']} / {Bg['standard_first_shown']} / {Bg['narrow_first_shown']} |"]
    out += ["", "## T5e. Per-run branch-resolution trace (BRANCH TREATMENT)", "", "| Run | H3 body | selector shown | condition shown | width source shown | Standard shown | Narrow shown | Narrow first? | Narrow followed? | resolved (H4 exposed) | calls | backtrack | rank-1 category | gold rank |", "|---|---|---|---|---|---|---|---|---|---|---|---|---|---|"]
    for r in runs:
        if r["arm"] != "TREATMENT": continue
        b = r["branch"]; d = r["dispatch"]; out.append(f"| {r['run_id'].split('/')[1]} | {f(d['first_encounter_abstraction_step'])} | {f(b['selector_first_shown'])} | {f(b['condition_first_shown'])} | {f(b['width_source_line_shown'])} | {f(b['standard_first_shown'])} | {f(b['narrow_first_shown'])} | {b['wrong_branch_inspected_first']} | {b['wrong_branch_followed']} | {f(d['resolved_step'])} | {f(d['calls_spent_resolving'])} | {b['backtracking_occurred']} | {b['rank1_category']} | {r['gold_rank']} |")
out += ["", "## T6. Contract-evidence markers: first exposure step (tool OUTPUT), per run", ""]
marks = list(runs[0]["contract_first_shown"].keys()) if runs else []
out += ["| Marker | " + " | ".join(r["run_id"].replace("CONVERSION-BRANCH-", "").replace("-01/run-", "/") for r in runs) + " |", "|---|" + "---|" * len(runs)]
for m in marks: out.append(f"| `{m}` | " + " | ".join(f(r["contract_first_shown"].get(m)) for r in runs) + " |")
out += ["| gold first exposed | " + " | ".join(f(r["gold_first_exposed_step"]) for r in runs) + " |", "| buggy line first shown | " + " | ".join(f(r["buggy_line_first_shown"]) for r in runs) + " |"]
out += ["", "## T7. Novel search vocabulary events", "", "| Run | Step | Token | Command |", "|---|---|---|---|"]; n = 0
for r in runs:
    for e in r["novel_search_vocabulary"]: n += 1; out.append(f"| {r['run_id'].split('/')[1]} ({r['arm']}) | {e['step']} | `{e['token']}` | `{e['command'][:100]}` |")
if n == 0: out.append("| (none) | - | - | - |")
out += ["", "## T8. Submitted top-5 per run", "", "| Run | Arm | 1 | 2 | 3 | 4 | 5 |", "|---|---|---|---|---|---|---|"]
for r in runs: t = r["top10"] + [""] * 5; out.append(f"| {r['run_id'].split('/')[1]} | {r['arm']} | " + " | ".join(f"`{x.split('.')[-1]}`" if x else "-" for x in t[:5]) + " |")
open(sys.argv[2], "w").write("\n".join(out) + "\n"); print("\n".join(out[:12]))
